30	export interface DuelResult {
31	  readonly ok: boolean;
32	  readonly rejection: LedgerRejection | null;
33	  /** The duel as it now stands (its current result for a rejected request), or null for an unknown duel. */
34	  readonly duel: LedgerDuel | null;
35	  readonly transfers: readonly Transfer[];
36	  readonly cacheIds: readonly string[];
37	}
38	
39	function rejected(state: LedgerState, rejection: LedgerRejection, duelId: unknown): LedgerStep<DuelResult> {
40	  const duel = typeof duelId === "string" ? (findDuel(state, duelId) ?? null) : null;
41	  return { state, result: { ok: false, rejection, duel, transfers: [], cacheIds: [] } };
42	}
43	
44	function applied(state: LedgerState, duelId: string, effects: Effects): LedgerStep<DuelResult> {
45	  return {
46	    state,
47	    result: { ok: true, rejection: null, duel: findDuel(state, duelId) ?? null, ...effects },
48	  };
49	}
50	
51	function replaceDuel(state: LedgerState, duel: LedgerDuel): LedgerState {
52	  return { ...state, duels: state.duels.map((existing) => (existing.id === duel.id ? duel : existing)) };
53	}
54	
55	export interface ReserveDuelRequest {
56	  /** Created by the server for the encounter. */
57	  readonly duelId: string;
58	  readonly players: readonly [string, string];
59	  readonly tick: number;
60	}
61	
62	/**
63	 * Reserves both players' rubbings inside the duel (§4, §16), so none of them can be collected, stolen or abandoned
64	 * twice while it runs, and cancels both players' channels. A disconnected player can be challenged (§12).
65	 */
66	export function reserveDuel(state: LedgerState, request: ReserveDuelRequest): LedgerStep<DuelResult> {
67	  const { duelId, players, tick } = request;
68	  const bad = tickRejection(state, tick);
69	  if (bad) return rejected(state, bad, duelId);
70	  if (!isPlayerId(duelId) || !Array.isArray(players) || players.length !== 2) return rejected(state, "invalid-request", duelId);
71	  if (findDuel(state, duelId)) return rejected(state, "duplicate", duelId);
72	  const [a, b] = players;
73	  if (a === b) return rejected(state, "same-player", duelId);
74	  for (const playerId of players) {
75	    const refusal = playerRejection(state, playerId) ?? (activeDuelOf(state, playerId) ? "player-in-duel" : null);
76	    if (refusal) return rejected(state, refusal, duelId);
77	  }
78	  const effects = noEffects();
79	  const duel: LedgerDuel = {
80	    id: duelId,
81	    players: [a, b],
82	    startTick: tick,
83	    phase: "fighting",
84	    result: null,
85	    choiceDeadline: null,
86	    settlement: null,
87	  };
88	  let next: LedgerState = { ...atTick(state, tick), duels: [...state.duels, duel] };
89	  for (const playerId of players) next = updatePlayer(next, playerId, (player) => ({ ...player, channel: null }));
90	  next = moveRubbings(
91	    next,
92	    next.rubbings.flatMap((rubbing) =>
93	      rubbing.location.kind === "player" && players.includes(rubbing.location.playerId)
94	        ? [{ rubbingId: rubbing.id, to: { kind: "duel", duelId, playerId: rubbing.location.playerId } as const }]
95	        : [],
96	    ),
97	    effects,
98	  );
99	  return applied(next, duelId, effects);
100	}
101	
102	export interface ReportDuelResultRequest {
103	  readonly duelId: string;
104	  readonly tick: number;
105	  /** `cancelled`: both players forfeited on the same tick (§12), which settles like a draw. */
106	  readonly outcome: "win" | "draw" | "cancelled";
107	  /** The winner, for `win` only. */
108	  readonly winner?: string;
109	}
110	
111	/**
112	 * Records the fight's result once. A draw or cancellation settles at once with nothing moving. A win opens the
113	 * winner's theft choice window, or settles at once (gold only) when no type is eligible. Any later result message
114	 * for the duel, even a different one, changes nothing and returns the current result.
115	 */
116	export function reportDuelResult(state: LedgerState, request: ReportDuelResultRequest): LedgerStep<DuelResult> {
117	  const { duelId, tick, outcome, winner } = request;
118	  const bad = tickRejection(state, tick);
119	  if (bad) return rejected(state, bad, duelId);
120	  const duel = typeof duelId === "string" ? findDuel(state, duelId) : undefined;
121	  if (!duel) return rejected(state, "unknown-duel", duelId);
122	  if (duel.phase !== "fighting") return rejected(state, "already-resolved", duelId);
123	  if (outcome === "win") {
124	    if (winner === undefined || !duel.players.includes(winner)) return rejected(state, "not-a-participant", duelId);
125	  } else if ((outcome !== "draw" && outcome !== "cancelled") || winner !== undefined) {
126	    return rejected(state, "invalid-request", duelId);
127	  }
128	  const effects = noEffects();
129	  const next = recordResult(atTick(state, tick), duel, outcome, winner ?? null, false, tick, effects);
130	  return applied(next, duelId, effects);
131	}
132	
133	/**
134	 * Records a result for a duel still fighting; shared with a forfeit by a player who leaves. A forfeit win never
135	 * commits within its own tick, even with no type eligible (its window then closes on the next tick), so that the
136	 * opponent leaving on the same tick can still turn it into §12's cancellation, whatever order the two arrive in.
137	 */
138	export function recordResult(
139	  state: LedgerState,
140	  duel: LedgerDuel,
141	  outcome: DuelResultRecord["outcome"],
142	  winner: string | null,
143	  forfeit: boolean,
144	  tick: number,
145	  effects: Effects,
146	): LedgerState {
147	  if (outcome !== "win") {
148	    const result: DuelResultRecord = { outcome, winner: null, loser: null, forfeit, tick };
149	    const settlement: DuelSettlement = {
150	      tick,
151	      stolenRubbingId: null,
152	      stolenType: null,
153	      choice: "none",
154	      gold: 0,
155	      goldSuppressed: false,
156	    };
157	    let next = replaceDuel(state, { ...duel, phase: "settled", result, settlement });
158	    for (const playerId of duel.players) {
159	      next = releaseTo(next, playerId, reservedIn(next, duel.id, playerId).map((rubbing) => rubbing.id), tick, effects);
160	    }
161	    return next;
162	  }
163	  const loser = duel.players[0] === winner ? duel.players[1] : duel.players[0];
164	  const decided: LedgerDuel = { ...duel, result: { outcome, winner, loser, forfeit, tick } };
165	  const next = replaceDuel(state, decided);
166	  const eligible = eligibleTheftTypes(next, duel.id).length > 0;
167	  if (!eligible && !forfeit) return commitWin(next, decided, tick, null, effects);
168	  const window = eligible ? state.rules.theftChoiceTicks : 1;
169	  return replaceDuel(next, { ...decided, phase: "choosing", choiceDeadline: tick + window });
170	}
171	
172	/**
173	 * Commits a decided duel, once: validates eligibility again, moves the stolen rubbing (the winner's valid choice, or
174	 * the default), transfers gold unless suppressed, grants the loser a fresh rumor for the lost type, and returns every
175	 * other reserved rubbing to its owner (or to a cache where its owner left). A winner who has left takes nothing.
176	 */
177	export function commitWin(
178	  state: LedgerState,
179	  duel: LedgerDuel,
180	  tick: number,
181	  choice: RubbingType | null,
182	  effects: Effects,
183	): LedgerState {
184	  const result = duel.result;
185	  if (duel.phase === "settled" || result?.outcome !== "win" || result.winner === null || result.loser === null) {
186	    throw new Error(`duel ${duel.id} has no win to commit`);
187	  }
188	  const { winner, loser } = result;
189	  const winnerPlayer = findPlayer(state, winner);
190	  const loserPlayer = findPlayer(state, loser);
191	  if (!winnerPlayer || !loserPlayer) throw new Error(`duel ${duel.id} names an unknown player`);
192	  const winnerPresent = winnerPlayer.status !== "left";
193	
194	  const eligible = eligibleTheftTypes(state, duel.id);
195	  const chosen = choice !== null && eligible.includes(choice) ? choice : null;
196	  const stolenType = chosen ?? defaultTheftType(state, eligible);
197	  const stolen = stolenType === null ? undefined : reservedIn(state, duel.id, loser).find((rubbing) => rubbing.type === stolenType);
198	
199	  const previous = state.wins.find((win) => win.winner === winner && win.loser === loser);
200	  const goldSuppressed =
201	    winnerPresent && previous !== undefined && result.tick - previous.tick < state.rules.repeatWinWindowTicks;
202	  const gold = winnerPresent && !goldSuppressed ? pvpGoldTransfer(state.rules, loserPlayer.gold) : 0;
203	
204	  const settlement: DuelSettlement = {
205	    tick,
206	    stolenRubbingId: stolen?.id ?? null,
207	    stolenType: stolen ? stolen.type : null,
208	    choice: stolen === undefined ? "none" : chosen !== null ? "winner" : "default",
209	    gold,
210	    goldSuppressed,
211	  };
212	  let next = replaceDuel(state, { ...duel, phase: "settled", settlement });
213	  if (stolen) {
214	    next = moveRubbings(next, [{ rubbingId: stolen.id, to: { kind: "player", playerId: winner } }], effects);
215	    const lost = stolen.type;
216	    next = updatePlayer(next, loser, (player) => ({
217	      ...player,
218	      freshRumors: player.freshRumors.includes(lost) ? player.freshRumors : [...player.freshRumors, lost].sort(byTypeOrder),
219	    }));
220	  }
221	  if (gold > 0) {
222	    next = updatePlayer(next, loser, (player) => ({ ...player, gold: player.gold - gold }));
223	    next = updatePlayer(next, winner, (player) => ({ ...player, gold: player.gold + gold }));
224	  }
225	  if (winnerPresent) {
226	    const record = { winner, loser, tick: result.tick };
227	    next = {
228	      ...next,
229	      wins: previous ? next.wins.map((win) => (win === previous ? record : win)) : [...next.wins, record],
230	    };
231	  }
232	  for (const playerId of [winner, loser]) {
233	    next = releaseTo(next, playerId, reservedIn(next, duel.id, playerId).map((rubbing) => rubbing.id), tick, effects);
234	  }
235	  return next;
236	}
237	
238	export interface ChooseTheftRequest {
239	  /** The server-created duel result the choice refers to (§16). */
240	  readonly duelId: string;
241	  readonly playerId: string;
242	  readonly type: RubbingType;
243	  readonly tick: number;
244	}
245	
246	/** The winner's theft choice, before the deadline and for an eligible type; it commits the settlement at once. */
247	export function chooseTheft(state: LedgerState, request: ChooseTheftRequest): LedgerStep<DuelResult> {
248	  const { duelId, playerId, type, tick } = request;
249	  const bad = tickRejection(state, tick);
250	  if (bad) return rejected(state, bad, duelId);
251	  const duel = typeof duelId === "string" ? findDuel(state, duelId) : undefined;
252	  if (!duel) return rejected(state, "unknown-duel", duelId);
253	  if (duel.phase === "settled") return rejected(state, "already-resolved", duelId);
254	  if (duel.phase !== "choosing" || duel.result === null || duel.choiceDeadline === null) {
255	    return rejected(state, "not-choosing", duelId);
256	  }
257	  if (playerId !== duel.result.winner) return rejected(state, "not-winner", duelId);
258	  if (tick >= duel.choiceDeadline) return rejected(state, "choice-window-closed", duelId);
259	  if (!rubbingTypeSchema.safeParse(type).success || !eligibleTheftTypes(state, duelId).includes(type)) {
260	    return rejected(state, "ineligible-type", duelId);
261	  }
262	  const effects = noEffects();
263	  const next = commitWin(atTick(state, tick), duel, tick, type, effects);
264	  return applied(next, duelId, effects);
265	}
266	
267	export interface AdvanceRequest {
268	  readonly tick: number;
269	}
270	
271	export interface AdvanceResult {
272	  readonly ok: boolean;
273	  readonly rejection: LedgerRejection | null;
274	  /** Duels whose choice window closed at this tick, settled with the default theft. */
275	  readonly settled: readonly LedgerDuel[];
276	  readonly transfers: readonly Transfer[];
277	  readonly cacheIds: readonly string[];
278	}
279	
280	/**
281	 * Moves the ledger's clock to `tick` and settles every duel whose choice window has closed with the default theft,
282	 * in reservation order. Call it once per world tick before that tick's requests.
283	 */
284	export function advanceLedger(state: LedgerState, request: AdvanceRequest): LedgerStep<AdvanceResult> {
285	  const bad = tickRejection(state, request.tick);
286	  if (bad) return { state, result: { ok: false, rejection: bad, settled: [], transfers: [], cacheIds: [] } };
287	  const { tick } = request;
288	  const effects = noEffects();
289	  let next = atTick(state, tick);
290	  const settled: string[] = [];
291	  for (const duel of state.duels) {
292	    if (duel.phase === "choosing" && duel.choiceDeadline !== null && tick >= duel.choiceDeadline) {
293	      next = commitWin(next, findDuel(next, duel.id)!, tick, null, effects);
294	      settled.push(duel.id);
295	    }
296	  }
297	  return {
298	    state: next,
299	    result: { ok: true, rejection: null, settled: settled.map((id) => findDuel(next, id)!), ...effects },
300	  };
301	}
